import { ProductNotFound } from "@/features/products/components/ProductNotFound"

/**
 * The page for a product that does not exist, under the 404 status the product page sets: the
 * module's own state, with the way back to the list, in place of the app's generic one.
 */
export default function NotFound() {
  return (
    <main className="mx-auto w-full max-w-4xl flex-1 px-4 py-6 sm:px-6">
      <ProductNotFound />
    </main>
  )
}

import { cache } from "react"
import type { Metadata } from "next"
import { notFound } from "next/navigation"

import { defaultMetadata } from "@/config/seo.config"
import { siteConfig } from "@/config/site.config"

import { getInitialProduct } from "@/features/products/api/get-initial-product.api"
import { ProductDetail } from "@/features/products/components/ProductDetail"
import { getProductHref } from "@/features/products/helpers/product-href"
import {
  getProductImage,
  getProductJsonLd,
  toJsonLd
} from "@/features/products/helpers/product-seo"

type PageProps = {
  params: Promise<{ id: string }>
}

// The metadata and the page both need the product, so they share one request per render.
const loadProduct = cache((id: string) => getInitialProduct(Promise.resolve({ id })))

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { product } = await loadProduct((await params).id)
  // A request that failed; the page leaves the product to the client. A missing product never
  // gets here with metadata of its own, since the page calls `notFound()`.
  if (!product) return { title: "Product" }

  const { title, description } = product
  const url = getProductHref(product.id)
  const images = [{ url: getProductImage(product), alt: title }]

  return {
    title,
    description,
    alternates: { canonical: url },
    // A page replaces the whole `openGraph` and `twitter` of the layout, so the site's stay in.
    openGraph: { ...defaultMetadata.openGraph, title, description, url, images },
    twitter: { ...defaultMetadata.twitter, title, description, images }
  }
}

/**
 * The server fetches the product, so its HTML already has it, and a product that does not exist
 * answers with a real 404. A request that fails otherwise leaves the product to the client.
 */
export default async function Page({ params }: PageProps) {
  const initialProduct = await loadProduct((await params).id)
  if (initialProduct.notFound) notFound()
  const { product } = initialProduct

  return (
    <main className="mx-auto w-full max-w-4xl flex-1 px-4 py-6 sm:px-6">
      {product && (
        // Product data for search results, as Next.js advises: a script in the page.
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{
            __html: toJsonLd(
              getProductJsonLd(product, `${siteConfig.url}${getProductHref(product.id)}`)
            )
          }}
        />
      )}
      <ProductDetail initialProduct={initialProduct} />
    </main>
  )
}

import { cache } from "react"
import type { Metadata } from "next"

import type { SearchParams } from "nuqs/server"

import { defaultMetadata } from "@/config/seo.config"

import { getInitialProducts } from "@/features/products/api/get-initial-products.api"
import { ProductList } from "@/features/products/components/ProductList"
import { ProductListTitle } from "@/features/products/components/ProductListTitle"
import { getProductsCanonicalHref } from "@/features/products/helpers/product-href"
import { getProductListFacts, getProductListText } from "@/features/products/helpers/product-seo"
import { loadProductListParams } from "@/features/products/schemas/product-list-params.schema"

type PageProps = {
  searchParams: Promise<SearchParams>
}

// The metadata and the page both need the list, so they share one request per render.
const loadList = cache((search: string) => getInitialProducts(Promise.resolve(JSON.parse(search))))

export async function generateMetadata({ searchParams }: PageProps): Promise<Metadata> {
  const search = await searchParams
  const [params, initial] = await Promise.all([
    loadProductListParams(Promise.resolve(search)),
    loadList(JSON.stringify(search))
  ])
  const facts = getProductListFacts(params, initial.data, initial.categories)
  const { title, description } = getProductListText(facts)
  const url = getProductsCanonicalHref(params)
  const images = facts.image ? [{ url: facts.image, alt: title }] : undefined

  return {
    title,
    description,
    alternates: { canonical: url },
    // A page replaces the whole `openGraph` and `twitter` of the layout, so the site's stay in.
    openGraph: { ...defaultMetadata.openGraph, title, description, url, ...(images && { images }) },
    twitter: { ...defaultMetadata.twitter, title, description, ...(images && { images }) },
    // Search results are not pages of their own; their links are still followed.
    ...(facts.query && { robots: { index: false, follow: true } })
  }
}

/**
 * The server fetches the page the URL asks for, so the first HTML already lists the products.
 * Other pages, filters and sorting load on the client.
 */
export default async function Page({ searchParams }: PageProps) {
  const initialProducts = await loadList(JSON.stringify(await searchParams))

  return (
    <main className="mx-auto flex w-full max-w-4xl flex-1 flex-col gap-4 px-4 py-6 sm:px-6">
      <h1 className="text-2xl font-semibold tracking-tight">Products</h1>
      {/*
        No Suspense boundary: the page reads `searchParams`, so it renders per request and nuqs has
        the URL on the server. A boundary here would let the list stream in later, hidden until
        JavaScript shows it.
      */}
      <ProductList initialProducts={initialProducts} />
      <ProductListTitle initialProducts={initialProducts} />
    </main>
  )
}

import { api } from "@/lib/api"

import { PRODUCTS_PATH } from "@/features/products/constants/products.constants"
import { productCategorySchema } from "@/features/products/schemas/product.schema"
import type { ProductCategory } from "@/features/products/schemas/product.schema"

export function getCategories(signal?: AbortSignal): Promise<ProductCategory[]> {
  return api.get(`${PRODUCTS_PATH}/categories`, { schema: productCategorySchema.array(), signal })
}

import { getProduct } from "@/features/products/api/get-product.api"
import type { InitialProduct } from "@/features/products/api/product.queries"
import { isNotFoundError } from "@/features/products/helpers/get-error-message"
import { productIdSchema } from "@/features/products/schemas/product.schema"

/**
 * Fetches on the server the product `ProductDetail` shows first, from the page's `params`. A wrong
 * id or a 404 sets `notFound`, so the page can call Next.js `notFound()`. Any other failure leaves
 * the product to the client, which then shows its error state and retries.
 */
export async function getInitialProduct(params: Promise<{ id: string }>): Promise<InitialProduct> {
  const updatedAt = Date.now()
  const result = productIdSchema.safeParse((await params).id)
  if (!result.success) return { product: null, notFound: true, updatedAt }

  try {
    return { product: await getProduct(result.data), notFound: false, updatedAt }
  } catch (error) {
    return { product: null, notFound: isNotFoundError(error), updatedAt }
  }
}

import type { SearchParams } from "nuqs/server"

import { getCategories } from "@/features/products/api/get-categories.api"
import { getProducts } from "@/features/products/api/get-products.api"
import { productsQueryOptions, toQueryFilters } from "@/features/products/api/product.queries"
import type { InitialProducts } from "@/features/products/api/product.queries"
import { loadProductListParams } from "@/features/products/schemas/product-list-params.schema"

/**
 * Fetches on the server what `ProductList` shows first: the page the URL asks for and the
 * categories. A request that fails gives `null`, and the client then fetches it itself.
 */
export async function getInitialProducts(
  searchParams: Promise<SearchParams>
): Promise<InitialProducts> {
  const filters = toQueryFilters(await loadProductListParams(searchParams))
  const [data, categories] = await Promise.all([
    getProducts(filters).catch(() => null),
    getCategories().catch(() => null)
  ])

  return {
    queryKey: productsQueryOptions(filters).queryKey,
    data,
    categories,
    updatedAt: Date.now()
  }
}

import { api } from "@/lib/api"

import { PRODUCTS_PATH } from "@/features/products/constants/products.constants"
import { productDetailsSchema } from "@/features/products/schemas/product.schema"
import type { ProductDetails } from "@/features/products/schemas/product.schema"

export function getProduct(id: number, signal?: AbortSignal): Promise<ProductDetails> {
  return api.get(`${PRODUCTS_PATH}/${id}`, { schema: productDetailsSchema, signal })
}

import { http, HttpResponse } from "msw/http"
import { describe, expect, it } from "vitest"

import { siteConfig } from "@/config/site.config"

import { getProducts } from "@/features/products/api/get-products.api"
import { PRODUCTS_PATH } from "@/features/products/constants/products.constants"
import { server } from "@/test/server"

const PRODUCTS_URL = `${siteConfig.apiUrl}${PRODUCTS_PATH}`

const mascara = {
  id: 1,
  title: "Essence Mascara Lash Princess",
  brand: "Essence",
  price: 9.99,
  discountPercentage: 10.48,
  rating: 2.56,
  availabilityStatus: "In Stock",
  thumbnail:
    "https://cdn.dummyjson.com/product-images/beauty/essence-mascara-lash-princess/thumbnail.webp"
}

function pageOf(products: unknown[], skip = 0) {
  return { products, total: products.length, skip, limit: 24 }
}

function captureParams(url: string) {
  const captured: { params?: URLSearchParams } = {}
  server.use(
    http.get(url, ({ request }) => {
      captured.params = new URL(request.url).searchParams
      return HttpResponse.json(pageOf([mascara], 48))
    })
  )
  return captured
}

describe("getProducts", () => {
  it("asks for the page's products and only for the card's fields", async () => {
    const captured = captureParams(PRODUCTS_URL)

    await expect(getProducts({ page: 3, q: "", category: "", sort: "featured" })).resolves.toEqual(
      pageOf([mascara], 48)
    )
    expect(captured.params?.get("limit")).toBe("24")
    expect(captured.params?.get("skip")).toBe("48")
    expect(captured.params?.get("select")).toContain("thumbnail")
    expect(captured.params?.has("q")).toBe(false)
    expect(captured.params?.has("sortBy")).toBe(false)
  })

  it("searches on its own endpoint, even with a category", async () => {
    const captured = captureParams(`${PRODUCTS_URL}/search`)

    await getProducts({ page: 1, q: "phone", category: "beauty", sort: "price-desc" })
    expect(captured.params?.get("q")).toBe("phone")
    expect(captured.params?.get("sortBy")).toBe("price")
    expect(captured.params?.get("order")).toBe("desc")
  })

  it("lists a category on its own endpoint", async () => {
    const captured = captureParams(`${PRODUCTS_URL}/category/smartphones`)

    await getProducts({ page: 1, q: "", category: "smartphones", sort: "discount" })
    expect(captured.params?.get("sortBy")).toBe("discountPercentage")
  })

  it("accepts a product without a brand or a discount", async () => {
    const { brand: _brand, discountPercentage: _discount, ...plain } = mascara
    server.use(http.get(PRODUCTS_URL, () => HttpResponse.json(pageOf([plain]))))

    const { products } = await getProducts({ page: 1, q: "", category: "", sort: "featured" })
    expect(products[0]?.brand).toBeUndefined()
    expect(products[0]?.discountPercentage).toBe(0)
  })
})

import { api } from "@/lib/api"

import {
  PRODUCT_FIELDS,
  PRODUCT_SORTS,
  PRODUCTS_PAGE_SIZE,
  PRODUCTS_PATH
} from "@/features/products/constants/products.constants"
import type { ProductsFilters } from "@/features/products/schemas/product-list-params.schema"
import { productsPageSchema } from "@/features/products/schemas/product.schema"
import type { ProductsPage } from "@/features/products/schemas/product.schema"

/** DummyJSON cannot search inside a category, so a search covers every category. */
function getPath({ q, category }: ProductsFilters) {
  if (q) return `${PRODUCTS_PATH}/search`
  if (category) return `${PRODUCTS_PATH}/category/${encodeURIComponent(category)}`
  return PRODUCTS_PATH
}

/** One page of the list, the first being `page: 1`. */
export function getProducts(filters: ProductsFilters, signal?: AbortSignal): Promise<ProductsPage> {
  const { sortBy, order } = PRODUCT_SORTS[filters.sort]

  return api.get(getPath(filters), {
    params: {
      limit: PRODUCTS_PAGE_SIZE,
      skip: (filters.page - 1) * PRODUCTS_PAGE_SIZE,
      q: filters.q || undefined,
      select: PRODUCT_FIELDS,
      sortBy,
      order
    },
    schema: productsPageSchema,
    signal
  })
}

import { keepPreviousData, queryOptions } from "@tanstack/react-query"
import type { QueryKey } from "@tanstack/react-query"

import { getCategories } from "@/features/products/api/get-categories.api"
import { getProduct } from "@/features/products/api/get-product.api"
import { getProducts } from "@/features/products/api/get-products.api"
import { productKeys } from "@/features/products/api/query-keys"
import { PRODUCTS_STALE_TIME } from "@/features/products/constants/products.constants"
import type { ProductsFilters } from "@/features/products/schemas/product-list-params.schema"
import type {
  ProductCategory,
  ProductDetails,
  ProductsPage
} from "@/features/products/schemas/product.schema"

/** What the server fetched for the first paint: one page of the list, and the categories. */
export type InitialProducts = {
  queryKey: QueryKey
  /** `null` when the request failed, so the client fetches it. */
  data: ProductsPage | null
  categories: ProductCategory[] | null
  updatedAt: number
}

/** What the server fetched for a product's page. `notFound` lets the page answer with a 404. */
export type InitialProduct = {
  product: ProductDetails | null
  notFound: boolean
  updatedAt: number
}

/** A search ignores the category, so both share one cache entry and one request. */
export function toQueryFilters({ q, category, sort, page }: ProductsFilters): ProductsFilters {
  const search = q.trim()
  return { q: search, category: search ? "" : category, sort, page }
}

export const productsQueryOptions = (params: ProductsFilters) => {
  const filters = toQueryFilters(params)

  return queryOptions({
    queryKey: productKeys.list(filters),
    queryFn: ({ signal }) => getProducts(filters, signal),
    // The page on screen stays, dimmed, while the next one loads.
    placeholderData: keepPreviousData,
    staleTime: PRODUCTS_STALE_TIME
  })
}

export const categoriesQueryOptions = () =>
  queryOptions({
    queryKey: productKeys.categories(),
    queryFn: ({ signal }) => getCategories(signal),
    // The category list barely changes, so one request per visit is enough.
    staleTime: Infinity
  })

export const productQueryOptions = (id: number) =>
  queryOptions({
    queryKey: productKeys.detail(id),
    queryFn: ({ signal }) => getProduct(id, signal),
    staleTime: PRODUCTS_STALE_TIME
  })

import { ArrowLeftIcon } from "lucide-react"

import { buttonVariants } from "@/components/ui/button"
import { ProductLink } from "@/features/products/components/ProductLink"

/** Back to the list, from a product or from a product that is not there. */
export function ProductBackLink() {
  return (
    <ProductLink className={buttonVariants({ variant: "ghost", size: "sm" })}>
      <ArrowLeftIcon aria-hidden />
      All products
    </ProductLink>
  )
}

import { Badge } from "@/components/ui/badge"
import { Card, CardContent } from "@/components/ui/card"
import { ProductImage } from "@/features/products/components/ProductImage"
import { ProductLink } from "@/features/products/components/ProductLink"
import { ProductPrice } from "@/features/products/components/ProductPrice"
import { ProductRating } from "@/features/products/components/ProductRating"
import {
  DISCOUNT_BADGE_CLASS_NAME,
  STOCK_LABELS
} from "@/features/products/constants/products.constants"
import { getDiscountLabel } from "@/features/products/helpers/price"
import type { Product } from "@/features/products/schemas/product.schema"

type ProductCardProps = {
  product: Product
  /** Loads the image at once, for cards in the first row. */
  eager?: boolean
}

export function ProductCard({ product, eager = false }: ProductCardProps) {
  const discount = getDiscountLabel(product.discountPercentage)
  const stock = STOCK_LABELS[product.availabilityStatus]

  return (
    // The title is the link and stretches over the card, so the whole card opens the product while
    // screen readers hear only its name.
    <Card className="relative h-full gap-0 py-0 transition-shadow hover:shadow-md has-[a:focus-visible]:ring-[3px] has-[a:focus-visible]:ring-ring/50">
      <div className="relative aspect-square bg-muted/50">
        <ProductImage src={product.thumbnail} eager={eager} />
        {(discount || stock) && (
          <div className="absolute top-2 left-2 flex flex-wrap gap-1">
            {discount && (
              <Badge variant="destructive" className={DISCOUNT_BADGE_CLASS_NAME}>
                {discount}
              </Badge>
            )}
            {stock && <Badge variant="secondary">{stock}</Badge>}
          </div>
        )}
      </div>
      <CardContent className="flex flex-1 flex-col gap-1 p-3 sm:p-4">
        {product.brand && <p className="truncate text-xs text-muted-foreground">{product.brand}</p>}
        <h2 className="line-clamp-2 text-sm font-medium">
          <ProductLink
            productId={product.id}
            className="outline-none after:absolute after:inset-0 after:content-['']"
          >
            {product.title}
          </ProductLink>
        </h2>
        <ProductRating rating={product.rating} />
        <div className="mt-auto pt-2">
          <ProductPrice price={product.price} discountPercentage={product.discountPercentage} />
        </div>
      </CardContent>
    </Card>
  )
}

"use client"

import { useEffect, useState } from "react"
import type { KeyboardEvent, ReactNode } from "react"

import { ChevronLeftIcon, ChevronRightIcon } from "lucide-react"
import { cn } from "cn"
import useEmblaCarousel from "embla-carousel-react"

import { Button } from "@/components/ui/button"
import { ProductImage } from "@/features/products/components/ProductImage"

type ProductCarouselProps = {
  images: string[]
  title: string
  /** The image on screen. The carousel follows it and reports every move back. */
  selected: number
  onSelect: (index: number) => void
  /** Each slide's box, which sets the image's size. */
  slideClassName: string
  sizes: string
  /** Wraps a slide's image, such as in a button that opens it larger. */
  renderSlide?: (image: ReactNode, index: number) => ReactNode
  /** Shown over the top-right corner, such as the favourite button. */
  action?: ReactNode
}

/**
 * Embla, the engine shadcn's `carousel` wraps: that component needs a button size the templates
 * do not have. The page's gallery and the full-screen viewer both use this one.
 */
export function ProductCarousel({
  images,
  title,
  selected,
  onSelect,
  slideClassName,
  sizes,
  renderSlide = (image) => image,
  action
}: ProductCarouselProps) {
  const hasMany = images.length > 1
  // Read once: a changed option makes Embla start over, which would jump instead of slide.
  const [startIndex] = useState(selected)
  const [viewportRef, api] = useEmblaCarousel({ loop: hasMany, startIndex })

  // Swipes and arrows move the carousel itself, so the owner hears where it went.
  useEffect(() => {
    if (!api) return
    const onMove = () => onSelect(api.selectedScrollSnap())
    api.on("select", onMove)
    return () => {
      api.off("select", onMove)
    }
  }, [api, onSelect])

  // A thumbnail or the other carousel picked an image, so this one moves there.
  useEffect(() => {
    if (api && api.selectedScrollSnap() !== selected) api.scrollTo(selected)
  }, [api, selected])

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "ArrowLeft") api?.scrollPrev()
    if (event.key === "ArrowRight") api?.scrollNext()
  }

  return (
    <div className="flex flex-col gap-3">
      <div
        role="region"
        aria-roledescription="carousel"
        aria-label={`${title} images`}
        className="relative"
        onKeyDownCapture={onKeyDown}
      >
        <div ref={viewportRef} className="overflow-hidden rounded-xl">
          <div className="flex">
            {images.map((image, index) => (
              <div
                key={image}
                role="group"
                aria-roledescription="slide"
                aria-label={`${index + 1} of ${images.length}`}
                // A slide out of view is out of the tab order too, so focus cannot move the track
                // behind Embla's back.
                inert={index !== selected}
                className="min-w-0 shrink-0 grow-0 basis-full"
              >
                {renderSlide(
                  <div className={cn("relative bg-muted/50", slideClassName)}>
                    <ProductImage
                      src={image}
                      alt={hasMany ? `${title}, image ${index + 1} of ${images.length}` : title}
                      eager={index === selected}
                      sizes={sizes}
                    />
                  </div>,
                  index
                )}
              </div>
            ))}
          </div>
        </div>
        {hasMany && (
          <>
            <Button
              variant="secondary"
              size="icon"
              aria-label="Previous image"
              className="absolute top-1/2 left-3 -translate-y-1/2 rounded-full shadow-sm"
              onClick={() => api?.scrollPrev()}
            >
              <ChevronLeftIcon aria-hidden />
            </Button>
            <Button
              variant="secondary"
              size="icon"
              aria-label="Next image"
              className="absolute top-1/2 right-3 -translate-y-1/2 rounded-full shadow-sm"
              onClick={() => api?.scrollNext()}
            >
              <ChevronRightIcon aria-hidden />
            </Button>
          </>
        )}
        {action && <div className="absolute top-3 right-3">{action}</div>}
      </div>
      {hasMany && (
        // The padding leaves room for the focus and selection rings, which the scroll area clips.
        <ul aria-label="Images" className="flex gap-2 overflow-x-auto p-1">
          {images.map((image, index) => (
            <li key={image} className="shrink-0">
              <button
                type="button"
                aria-label={`Show image ${index + 1} of ${images.length}`}
                aria-pressed={index === selected}
                className={cn(
                  "relative block size-16 overflow-hidden rounded-md bg-muted/50 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50",
                  index === selected ? "ring-2 ring-primary" : "opacity-70 hover:opacity-100"
                )}
                onClick={() => onSelect(index)}
              >
                <ProductImage src={image} sizes="64px" />
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

import type { ReactNode } from "react"

import { useQueryClient } from "@tanstack/react-query"
import { screen, waitFor, within } from "@testing-library/react"
import userEvent from "@testing-library/user-event"
import { delay } from "msw"
import { http, HttpResponse } from "msw/http"
import { toast } from "sonner"
import { beforeAll, beforeEach, describe, expect, it, vi } from "vitest"

import { siteConfig } from "@/config/site.config"

import { getInitialProduct } from "@/features/products/api/get-initial-product.api"
import { productKeys } from "@/features/products/api/query-keys"
import { ProductDetail } from "@/features/products/components/ProductDetail"
import { PRODUCTS_PATH } from "@/features/products/constants/products.constants"
import { renderWithProviders } from "@/test/render"
import { server } from "@/test/server"

const params = vi.hoisted(() => ({ id: "1" }))
vi.mock("next/navigation", () => ({ useParams: () => params }))
vi.mock("sonner", () => ({ toast: { success: vi.fn() } }))

const PRODUCT_URL = `${siteConfig.apiUrl}${PRODUCTS_PATH}/:id`

const card = {
  id: 1,
  title: "Red Lipstick",
  brand: "Chic Cosmetics",
  category: "beauty",
  price: 10,
  discountPercentage: 10,
  rating: 4.4,
  availabilityStatus: "Low Stock",
  thumbnail: "https://cdn.dummyjson.com/1/thumbnail.webp"
}

const lipstick = {
  ...card,
  description: "A bold red that lasts all day.",
  images: ["https://cdn.dummyjson.com/1/1.webp", "https://cdn.dummyjson.com/1/2.webp"],
  tags: ["beauty", "lipstick"],
  sku: "BEA-CHI-LIP-004",
  stock: 4,
  weight: 1,
  dimensions: { width: 1, height: 2, depth: 3 },
  warrantyInformation: "1 year warranty",
  shippingInformation: "Ships overnight",
  returnPolicy: "30 days return policy",
  minimumOrderQuantity: 2,
  reviews: [
    {
      rating: 5,
      comment: "Great colour!",
      date: "2025-04-30T09:41:02.053Z",
      reviewerName: "Ada Lovelace",
      reviewerEmail: "ada@x.dummyjson.com"
    }
  ]
}

// jsdom has no layout, so the carousel finds none of the browser APIs it watches.
beforeAll(() => {
  class Observer {
    observe() {}
    unobserve() {}
    disconnect() {}
  }
  vi.stubGlobal("ResizeObserver", Observer)
  vi.stubGlobal("IntersectionObserver", Observer)
  vi.stubGlobal(
    "matchMedia",
    vi.fn(() => ({ matches: false, addEventListener() {}, removeEventListener() {} }))
  )
})

beforeEach(() => {
  params.id = "1"
})

/** Long enough for a request the component would send after its first render. */
function settle() {
  return new Promise((resolve) => setTimeout(resolve, 100))
}

describe("ProductDetail", () => {
  it("shows a loading state, then the whole product", async () => {
    server.use(http.get(PRODUCT_URL, () => HttpResponse.json(lipstick)))
    renderWithProviders(<ProductDetail />)

    expect(screen.getByRole("status", { name: "Loading product" })).toBeInTheDocument()

    expect(
      await screen.findByRole("heading", { level: 1, name: "Red Lipstick" })
    ).toBeInTheDocument()
    expect(screen.getByText("A bold red that lasts all day.")).toBeInTheDocument()
    expect(screen.getByText("Sale price $10.00, was $11.11")).toBeInTheDocument()
    expect(screen.getByText("Low stock")).toBeInTheDocument()
    expect(screen.getByText("4 in stock")).toBeInTheDocument()
    expect(screen.getByText("30 days return policy")).toBeInTheDocument()
    expect(screen.getByText("Great colour!")).toBeInTheDocument()
    // Reviewer emails are dropped by the schema, so they never reach the page.
    expect(screen.queryByText(/ada@x/)).not.toBeInTheDocument()
    expect(screen.getByRole("link", { name: "All products" })).toHaveAttribute("href", "/products")
  })

  it("confirms an add to cart with a toast", async () => {
    server.use(http.get(PRODUCT_URL, () => HttpResponse.json(lipstick)))
    const user = userEvent.setup()
    renderWithProviders(<ProductDetail />)

    await user.click(await screen.findByRole("button", { name: "Add to cart" }))

    expect(toast.success).toHaveBeenCalledWith("Added to cart", { description: "Red Lipstick" })
  })

  it("cannot add a product that is out of stock", async () => {
    server.use(
      http.get(PRODUCT_URL, () =>
        HttpResponse.json({ ...lipstick, availabilityStatus: "Out of Stock", stock: 0 })
      )
    )
    renderWithProviders(<ProductDetail />)

    expect(await screen.findByRole("button", { name: "Out of stock" })).toBeDisabled()
  })

  it("switches the large image from its thumbnails", async () => {
    server.use(http.get(PRODUCT_URL, () => HttpResponse.json(lipstick)))
    const user = userEvent.setup()
    renderWithProviders(<ProductDetail />)

    // Only the slide in view can take focus; the others are inert.
    expect(await screen.findByRole("group", { name: "1 of 2" })).not.toHaveAttribute("inert")
    expect(screen.getByRole("group", { name: "2 of 2" })).toHaveAttribute("inert")
    const second = screen.getByRole("button", { name: "Show image 2 of 2" })
    await user.click(second)
    expect(screen.getByRole("group", { name: "1 of 2" })).toHaveAttribute("inert")
    expect(screen.getByRole("group", { name: "2 of 2" })).not.toHaveAttribute("inert")

    expect(second).toHaveAttribute("aria-pressed", "true")
    expect(screen.getByRole("button", { name: "Show image 1 of 2" })).toHaveAttribute(
      "aria-pressed",
      "false"
    )
    expect(screen.getByRole("button", { name: "Next image" })).toBeInTheDocument()
  })

  it("opens the images full screen and keeps the image picked there", async () => {
    server.use(http.get(PRODUCT_URL, () => HttpResponse.json(lipstick)))
    const user = userEvent.setup()
    renderWithProviders(<ProductDetail />)

    const opener = await screen.findByRole("button", {
      name: "Open image 1 of 2 in full screen"
    })
    await user.click(opener)

    const viewer = await screen.findByRole("dialog", { name: "Red Lipstick" })
    await user.click(within(viewer).getByRole("button", { name: "Show image 2 of 2" }))
    expect(within(viewer).getByRole("button", { name: "Show image 2 of 2" })).toHaveAttribute(
      "aria-pressed",
      "true"
    )

    await user.keyboard("{Escape}")
    await waitFor(() => expect(screen.queryByRole("dialog")).not.toBeInTheDocument())
    expect(screen.getByRole("button", { name: "Show image 2 of 2" })).toHaveAttribute(
      "aria-pressed",
      "true"
    )
    // Focus lands on the image now on screen, not the one the viewer was opened from.
    expect(screen.getByRole("button", { name: "Open image 2 of 2 in full screen" })).toHaveFocus()
  })

  it("marks a favourite over the image and says so", async () => {
    server.use(http.get(PRODUCT_URL, () => HttpResponse.json(lipstick)))
    const user = userEvent.setup()
    renderWithProviders(<ProductDetail />)

    const favorite = await screen.findByRole("button", { name: "Favorite" })
    await user.click(favorite)

    expect(favorite).toHaveAttribute("aria-pressed", "true")
    expect(toast.success).toHaveBeenCalledWith("Added to favorites", {
      description: "Red Lipstick"
    })
  })

  it("shows the list card's fields at once while the rest loads", async () => {
    server.use(
      http.get(PRODUCT_URL, async () => {
        await delay(100)
        return HttpResponse.json(lipstick)
      })
    )
    function SeedList({ children }: { children: ReactNode }) {
      useQueryClient().setQueryData(
        productKeys.list({ q: "", category: "", sort: "featured", page: 1 }),
        { products: [card], total: 1, skip: 0, limit: 24 }
      )
      return children
    }
    renderWithProviders(
      <SeedList>
        <ProductDetail />
      </SeedList>
    )

    expect(screen.getByRole("heading", { level: 1, name: "Red Lipstick" })).toBeInTheDocument()
    expect(screen.queryByText("A bold red that lasts all day.")).not.toBeInTheDocument()
    expect(await screen.findByText("A bold red that lasts all day.")).toBeInTheDocument()
  })

  it("says the product is not found for an unknown id", async () => {
    server.use(
      http.get(PRODUCT_URL, () =>
        HttpResponse.json({ message: "Product with id '9999' not found" }, { status: 404 })
      )
    )
    params.id = "9999"
    renderWithProviders(<ProductDetail />)

    expect(await screen.findByText("Product not found")).toBeInTheDocument()
    expect(screen.getByRole("link", { name: "All products" })).toHaveAttribute("href", "/products")
  })

  it("trusts the server's not found, without asking the API again", async () => {
    let calls = 0
    server.use(
      http.get(PRODUCT_URL, () => {
        calls += 1
        return HttpResponse.json({ message: "Product with id '9999' not found" }, { status: 404 })
      })
    )
    params.id = "9999"

    const initial = await getInitialProduct(Promise.resolve({ id: "9999" }))
    expect(initial).toMatchObject({ product: null, notFound: true })
    renderWithProviders(<ProductDetail initialProduct={initial} />)

    expect(screen.getByText("Product not found")).toBeInTheDocument()
    await settle()
    expect(calls).toBe(1)
  })

  it.each(["abc", "0", "01", "1.0", "1e2", "0x10"])(
    "does not ask the API for %s, which is not a product id",
    async (id) => {
      let calls = 0
      server.use(
        http.get(PRODUCT_URL, () => {
          calls += 1
          return HttpResponse.json(lipstick)
        })
      )
      params.id = id
      renderWithProviders(<ProductDetail />)

      expect(screen.getByText("Product not found")).toBeInTheDocument()
      await expect(getInitialProduct(Promise.resolve({ id }))).resolves.toMatchObject({
        product: null,
        notFound: true
      })
      await settle()
      expect(calls).toBe(0)
    }
  )

  it("shows the error and retries", async () => {
    let calls = 0
    server.use(
      http.get(PRODUCT_URL, () => {
        calls += 1
        return calls === 1
          ? HttpResponse.json({ message: "Down" }, { status: 500 })
          : HttpResponse.json(lipstick)
      })
    )
    const user = userEvent.setup()
    renderWithProviders(<ProductDetail />)

    const alert = await screen.findByRole("alert")
    await user.click(within(alert).getByRole("button", { name: "Retry" }))

    expect(
      await screen.findByRole("heading", { level: 1, name: "Red Lipstick" })
    ).toBeInTheDocument()
  })

  it("renders the server's product without a request from the client", async () => {
    let calls = 0
    server.use(
      http.get(PRODUCT_URL, () => {
        calls += 1
        return HttpResponse.json(lipstick)
      })
    )

    const initial = await getInitialProduct(Promise.resolve({ id: "1" }))
    renderWithProviders(<ProductDetail initialProduct={initial} />)

    expect(screen.getByRole("heading", { level: 1, name: "Red Lipstick" })).toBeInTheDocument()
    await settle()
    expect(calls).toBe(1)
  })
})

